package com.yihe.framework.ehr;
import java.util.*;import java.util.concurrent.*;import javax.annotation.*;import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
/** Durable psychology queue: only pseudonymous, scored closed-choice data leave the server. */
@Component @SuppressWarnings("unchecked") public class QuestionnaireAnalysisWorker {
 final EhrRepository db;final EhrService ehr;final DigitalWorkerModelClient client;final TransactionTemplate tx;
 final ScheduledExecutorService clock=Executors.newSingleThreadScheduledExecutor();final ExecutorService pool=Executors.newFixedThreadPool(2);final java.util.concurrent.atomic.AtomicInteger active=new java.util.concurrent.atomic.AtomicInteger();
 public QuestionnaireAnalysisWorker(EhrRepository db,EhrService ehr,DigitalWorkerModelClient client,PlatformTransactionManager manager){this.db=db;this.ehr=ehr;this.client=client;tx=new TransactionTemplate(manager);}
 @PostConstruct public void start(){clock.scheduleWithFixedDelay(this::tick,5,3,TimeUnit.SECONDS);}
 long reminderTick;
 void reminders(){if(System.currentTimeMillis()-reminderTick<60000)return;reminderTick=System.currentTimeMillis();tx.execute(t->{for(Map<String,Object>r:db.all("SELECT x.*,l.document_json FROM a_questionnaire_assignments x JOIN a_questionnaire_releases l ON l.release_id=x.release_id LEFT JOIN a_questionnaire_responses s ON s.assignment_id=x.assignment_id WHERE l.release_status='active' AND s.response_id IS NULL AND (x.due_date IS NULL OR x.due_date>=CURDATE()) ORDER BY x.assigned_at LIMIT 1000 FOR UPDATE")){Map<String,Object>doc=(Map<String,Object>)ehr.decode(r.get("document_json")),config=doc.get("centerConfig") instanceof Map?(Map<String,Object>)doc.get("centerConfig"):Collections.emptyMap(),w=config.get("wizard") instanceof Map?(Map<String,Object>)config.get("wizard"):Collections.emptyMap(),release=w.get("release") instanceof Map?(Map<String,Object>)w.get("release"):Collections.emptyMap();if(!Boolean.TRUE.equals(release.get("reminder")))continue;int interval=Math.max(1,Math.min(30,(int)num(release.get("interval")))),max=Math.max(0,Math.min(10,(int)num(release.get("maxReminders"))));Map<String,Object>v=db.one("SELECT COUNT(*) n,MAX(created_at) last FROM a_questionnaire_deliveries WHERE assignment_id=? AND delivery_kind='reminder'",r.get("assignment_id"));if(num(v.get("n"))>=max)continue;Object last=v.get("last")==null?r.get("assigned_at"):v.get("last");if(db.count("SELECT ?<=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL ? DAY)",last,interval)!=1)continue;db.insert("a_questionnaire_deliveries",map("delivery_id",id(),"assignment_id",r.get("assignment_id"),"scope_code",r.get("scope_code"),"data_mode",r.get("data_mode"),"delivery_kind","reminder","delivery_state","in_app_available","created_at",now()));}return null;});}
 void tick(){try{reminders();db.exec("UPDATE a_questionnaire_processing SET ai_state='failed',ai_error='AI_WORKER_INTERRUPTED',updated_at=UTC_TIMESTAMP(6) WHERE ai_state='running' AND started_at<DATE_SUB(UTC_TIMESTAMP(),INTERVAL 15 MINUTE)");while(active.get()<2){Map<String,Object>job=tx.execute(t->{Map<String,Object>r=db.one("SELECT * FROM a_questionnaire_processing WHERE ai_state='queued' ORDER BY created_at LIMIT 1 FOR UPDATE");if(r!=null){r.put("claim_token",id());db.exec("UPDATE a_questionnaire_processing SET ai_state='running',claim_token=?,started_at=UTC_TIMESTAMP(6),attempts=attempts+1,updated_at=UTC_TIMESTAMP(6) WHERE response_id=?",r.get("claim_token"),r.get("response_id"));}return r;});if(job==null)break;active.incrementAndGet();pool.submit(()->{try{run(job);}finally{active.decrementAndGet();}});}}catch(RuntimeException e){/* Next tick retries a transient database outage. */}}
 public Map<String,Object> input(Map<String,Object>job){Map<String,Object> score=(Map<String,Object>)ehr.decode(job.get("score_json"));List<Object> scales=new ArrayList<>();for(Map<String,Object>s:QuestionnaireScoring.rows(score.get("scales"))){String code=str(s.get("name"));scales.add(map("instrument",Arrays.asList("PHQ-9","GAD-7").contains(code)?code:"本地自编调查","score",s.get("score"),"maxScore",s.get("maxScore"),"screeningLevel",s.get("risk"),"complete",s.get("complete")));}return map("task_type","psychological_assessment","worker_id","psychology","title","心理量表答卷辅助分析","instructions","逐量表解释后台计算的分值与关注等级，说明不等于诊断，给出访谈核实、复测与专业关注事项。不得改分、虚构历史或声称医生已审核；出现自伤条目信号时提示专业人员及时人工评估。","archive_context",map("temporarySubject",id(),"scales",scales,"urgentItemSignal",score.get("urgent"),"historyAvailable",false));}
 void run(Map<String,Object>job){String output=null,error=null;try{output=str(client.generate(input(job)).get("output"));require(!output.trim().isEmpty()&&output.length()<=20000,502,"AI_EMPTY_OR_OVERSIZED_RESPONSE");}catch(EhrException e){error=e.getMessage().matches("[A-Z0-9_]{1,100}")?e.getMessage():"AI_CONFIGURATION_OR_UPSTREAM_ERROR";}catch(RuntimeException e){error="AI_REQUEST_FAILED";}db.exec("UPDATE a_questionnaire_processing SET ai_state=?,ai_output=?,ai_error=?,finished_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6) WHERE response_id=? AND claim_token=? AND ai_state='running'",error==null?"completed":"failed",output,error,job.get("response_id"),job.get("claim_token"));}
 @PreDestroy public void stop(){clock.shutdownNow();pool.shutdownNow();}
}
